<?php
require __DIR__.'/bootstrap.php';if(!authorized()){header('Location: /backend-blog/login.php');exit;}
$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$all=posts(true);$id=(string)($_POST['id']??'');if(($_POST['action']??'')==='delete'){$all=array_values(array_filter($all,fn($p)=>$p['id']!==$id));save_posts($all);$notice='Article deleted';}else{$title=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));if(!$title||!$body)throw new RuntimeException('Title and body required');$old=null;foreach($all as $p){if($p['id']===$id)$old=$p;}if(!$old)$id=bin2hex(random_bytes(12));$media=upload_media($_FILES['media']??null);$entry=['id'=>$id,'slug'=>$old['slug']??('article-'.substr($id,0,12)),'title'=>$title,'summary'=>substr(trim((string)($_POST['summary']??'')),0,300),'body'=>$body,'image'=>($media&&preg_match('/\.(jpg|png|webp)$/',$media))?$media:($old['image']??''),'video'=>($media&&preg_match('/\.(mp4|webm)$/',$media))?$media:($old['video']??''),'youtube'=>(string)($_POST['youtube']??''),'status'=>in_array($_POST['status']??'', ['draft','published'],true)?$_POST['status']:'draft','date'=>$old['date']??gmdate('c')];$all=array_values(array_filter($all,fn($p)=>$p['id']!==$id));$all[]=$entry;save_posts($all);$notice='Article saved';}}catch(Throwable $e){$error=$e->getMessage();}}
$edit=null;foreach(posts(true) as $p){if($p['id']===($_GET['edit']??''))$edit=$p;}
?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Viana Blog Dashboard</title><link rel="stylesheet" href="/assets/css/blog-php.css"><header><a href="/blog.php">View blog</a><a href="/backend-blog/logout.php">Sign out</a></header><main class="wrap"><h1>Manage blog articles</h1><p><?=h($notice?:$error)?></p><section class="panel"><h2><?= $edit?'Edit article':'New article' ?></h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><label>Title<input name="title" maxlength="160" required value="<?=h($edit['title']??'')?>"></label><label>Summary<textarea name="summary" maxlength="300"><?=h($edit['summary']??'')?></textarea></label><label>Article<textarea name="body" rows="12" required><?=h($edit['body']??'')?></textarea></label><label>Photo or video<input name="media" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm"></label><label>YouTube video URL<input type="url" name="youtube" value="<?=h($edit['youtube']??'')?>"></label><label>Status<select name="status"><option value="draft" <?=($edit['status']??'')==='draft'?'selected':''?>>Draft</option><option value="published" <?=($edit['status']??'')==='published'?'selected':''?>>Published</option></select></label><button name="action" value="save">Save article</button></form></section><h2>Existing articles</h2><?php foreach(posts(true) as $p):?><div class="row"><?=h($p['title'])?> (<?=h($p['status'])?>) <a href="?edit=<?=h($p['id'])?>">Edit</a><form method="post" onsubmit="return confirm('Delete?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=h($p['id'])?>"><button name="action" value="delete">Delete</button></form></div><?php endforeach;?></main></html>